// One-off script that rasterizes public/favicon.svg (Coinlo's brand mark,
// also duplicated as `CoinloMark.tsx` for in-app use — keep all three in
// sync if the shape ever changes) into the PNG/ICO favicon sizes browsers
// and OSes actually need, plus renders og-image.svg into the 1200x630
// social-preview PNG referenced by index.html's Open Graph/Twitter tags.
//
// Not part of the build — these are static, checked-in output files, only
// regenerated by hand when the logo itself changes. Needs `sharp` (for
// SVG rendering) and Pillow (for the multi-resolution .ico), neither of
// which are project dependencies:
//   npm install --no-save sharp
//   pip install --break-system-packages pillow   # if not already present
//
// Usage: node scripts/generate-brand-assets.mjs

import sharp from 'sharp';
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const PUBLIC_DIR = new URL('../public/', import.meta.url);

async function renderPng(svgPath, size, outName) {
  await sharp(new URL(svgPath, PUBLIC_DIR)).resize(size, size).png().toFile(new URL(outName, PUBLIC_DIR));
}

const ogImageSvg = `
<svg width="1200" height="630" viewBox="0 0 1200 630" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <linearGradient id="bg" x1="0%" y1="0%" x2="100%" y2="100%">
      <stop offset="0%" stop-color="#1e5f8c" />
      <stop offset="100%" stop-color="#123a56" />
    </linearGradient>
  </defs>
  <rect width="1200" height="630" fill="url(#bg)" />
  <circle cx="220" cy="315" r="140" fill="#ffffff" fill-opacity="0.08" />
  <circle cx="220" cy="315" r="132" fill="#20699c" stroke="#0e2c43" stroke-width="4" />
  <circle cx="220" cy="315" r="102" fill="none" stroke="#ffffff" stroke-opacity="0.2" stroke-width="4" />
  <path d="M 263.3,264.1 A 67.5,67.5 0 1 0 263.3,365.9" fill="none" stroke="#ffffff" stroke-width="31" stroke-linecap="round" />
  <text x="420" y="345" font-family="Poppins" font-weight="700" font-size="118" fill="#ffffff">Coinlo</text>
  <text x="424" y="402" font-family="Poppins" font-weight="500" font-size="34" fill="#cfe4f4">Personal Budget &amp; Expense Tracker</text>
</svg>
`;

async function main() {
  await renderPng('favicon.svg', 16, 'icon-16-tmp.png');
  await renderPng('favicon.svg', 32, 'icon-32-tmp.png');
  await renderPng('favicon.svg', 48, 'icon-48-tmp.png');
  await renderPng('favicon.svg', 180, 'apple-touch-icon.png');
  await renderPng('favicon.svg', 192, 'icon-192.png');
  await renderPng('favicon.svg', 512, 'icon-512.png');

  const ogSvgPath = new URL('og-image-tmp.svg', PUBLIC_DIR);
  writeFileSync(ogSvgPath, ogImageSvg);
  await sharp(ogSvgPath).png().toFile(new URL('og-image.png', PUBLIC_DIR));

  // Pillow writes a proper multi-resolution .ico from the three PNGs above
  // (browsers/OSes pick whichever size they need out of the one file) —
  // sharp itself doesn't support .ico output.
  execFileSync('python3', [
    '-c',
    `
from PIL import Image
import sys
pub = sys.argv[1]
img16 = Image.open(pub + '/icon-16-tmp.png')
img32 = Image.open(pub + '/icon-32-tmp.png')
img48 = Image.open(pub + '/icon-48-tmp.png')
img48.save(pub + '/favicon.ico', format='ICO', sizes=[(16,16),(32,32),(48,48)], append_images=[img16, img32])
`,
    new URL('.', PUBLIC_DIR).pathname.replace(/\/$/, ''),
  ]);

  for (const tmp of ['icon-16-tmp.png', 'icon-32-tmp.png', 'icon-48-tmp.png', 'og-image-tmp.svg']) {
    execFileSync('rm', ['-f', new URL(tmp, PUBLIC_DIR).pathname]);
  }

  console.log('Brand assets written to public/.');
}

main();
